/**
 * Sprint 27R — Decision Support Shadow Capture Storage Adapter Plan: fixture corpus.
 *
 * A small, hand-authored corpus exercising `mapDecisionSupportCaptureRecordToStorageDraft()`,
 * `validateDecisionSupportShadowStorageDraft()`, and `simulateDecisionSupportShadowStorageAdapter()`
 * end to end. Each case either:
 *
 * - references a real Sprint 25R capture-harness fixture case id (`sourceCaptureHarnessCaseId`) —
 *   the test file re-runs that case through the real Sprint 24R -> Sprint 25R -> Sprint 27R pipeline
 *   (`prepareDecisionSupportShadowModeRun` -> `captureDecisionSupportShadowRun` ->
 *   `mapDecisionSupportCaptureRecordToStorageDraft`) to produce a real, policy-clean draft; or
 * - supplies `syntheticTopLevelOverrides`/`syntheticFieldOverrides` — a shallow-merge applied on top
 *   of that real draft (or its `fields`) to construct a synthetic policy-violating draft, proving each
 *   validation gate actually catches the violation it names, not merely trusts the mapper.
 *
 * None of this ever writes a database, calls Supabase, or persists anything outside this evaluation's
 * in-process return value — see `tests/playbook-engine-conversation-decision-support-shadow-storage-adapter-plan.test.mjs`.
 */

import type { DecisionSupportShadowCaptureMode } from "../../src/lib/playbook-engine/conversation/decision-support/decisionSupportShadowCaptureHarnessTypes";

export type DecisionSupportShadowStorageAdapterPlanCase = {
  id: string;
  scenario: string;
  /** References an id in DECISION_SUPPORT_SHADOW_CAPTURE_HARNESS_CASES (Sprint 25R fixtures). */
  sourceCaptureHarnessCaseId: string;
  /** Overrides the referenced case's own mode when set — otherwise its own `mode`/`contextOverrides.mode` is used. */
  captureMode?: DecisionSupportShadowCaptureMode;
  /** Shallow-merged onto the top level of the mapped draft, to construct a synthetic invalid draft. */
  syntheticTopLevelOverrides?: Record<string, unknown>;
  /** Shallow-merged onto `draft.fields`, to construct a synthetic invalid draft. */
  syntheticFieldOverrides?: Record<string, unknown>;
  expectedValid: boolean;
  expectedExcludedFields: string[];
  expectedIncludedFields: string[];
  expectedBlockingFailureCount: number;
  expectedWriteAttempted: false;
  expectedDbWriteAttempted: false;
  expectedSupabaseWriteAttempted: false;
  notes: string;
};

